// GOLD-001 — the first workspace this kit has ever produced, scored against the real scorers.
// Requirement: ai-evals.md · REQ-NF-007 · BR-002 · ADR-003 · ADR-006.
//
// Every other test in this suite checks the kit's PARTS. This one checks its OUTPUT: a
// workspace generated by following instructions/intake.md end to end against a clean
// repository, at express depth, using EV-001's answers.
//
// It exists because two whole classes of defect were invisible to part-tests and surfaced
// within minutes of a real run:
//
//   BUG-008  24 blueprints carried a worked example ADR-003 step 2 could not strip, so
//            "TeamTask Lite" and "SaaS task app" would have shipped as the developer's own
//            decisions. The C2 test skipped exactly those files.
//   BUG-010  Round 1 had to write its acceptance row into a file Round 8 owned, and the
//            change log had no table shaped like the row acceptance.mjs reads.
//
// A synthetic workspace built inside a test would have had neither problem, because the
// author of the test also authors the input. This fixture was not authored — it was produced.

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync, readdirSync, statSync } from 'node:fs'
import { join } from 'node:path'
import { score } from '../../ci/eval-runner.mjs'
import { acceptedStages, forbiddenStateFiles } from '../../ci/acceptance.mjs'
import { unfilled, todos, blueprintOf } from '../../ci/fill.mjs'

const ROOT = 'tests/fixtures/golden/EV-001-round1'

const walk = (d, acc = []) => {
  for (const e of readdirSync(d)) {
    const p = join(d, e)
    statSync(p).isDirectory() ? walk(p, acc) : acc.push(p)
  }
  return acc
}

const workspace = Object.fromEntries(
  walk(ROOT).map((p) => [p.slice(ROOT.length + 1).split('\\').join('/'), readFileSync(p, 'utf8')])
)

const library = readFileSync('plugin/blueprints/MANIFEST.md', 'utf8')
  .split('\n')
  .map((l) => (l.match(/^\| `([^`]+)` \|/) || [])[1])
  .filter(Boolean)

const changeLog = workspace['spec/01-docs/09-change-control/spec-change-log.md']

// --- What Round 1 produced -------------------------------------------------------------------

test('GOLD-001: Round 1 wrote the three files it owns', () => {
  assert.deepEqual(Object.keys(workspace).sort(), [
    'spec/01-docs/01-intent/intent.md',
    'spec/01-docs/01-intent/project-brief.md',
    'spec/01-docs/09-change-control/spec-change-log.md',
  ])
})

// --- BR-002: the failure that made BUG-008 worth finding --------------------------------------

test('GOLD-001: no example product reached the workspace', () => {
  // The regression that matters most. Before BUG-008 was fixed, filling intent.md left
  // "TeamTask Lite" in the developer's repository looking like a decision they had made.
  const all = Object.values(workspace).join('\n')
  for (const name of ['ProjectBoard', 'TeamTask Lite', 'SaaS task app', 'WORKED EXAMPLE']) {
    assert.doesNotMatch(all, new RegExp(name), `${name} must not survive the fill`)
  }
})

test('GOLD-001: every file carries a back-link that resolves to a real blueprint', () => {
  for (const [path, text] of Object.entries(workspace)) {
    const bp = blueprintOf(text)
    assert.ok(bp, `${path} has no back-link`)
    assert.ok(library.includes(bp), `${path} points at ${bp}, which is not in the library`)
  }
})

test('GOLD-001: no placeholder survived as body text', () => {
  for (const [path, text] of Object.entries(workspace)) {
    assert.deepEqual(unfilled(text), [], `${path} still holds an unfilled placeholder`)
  }
})

// --- ADR-006 / ADR-004: acceptance is a row, never a file -------------------------------------

test('GOLD-001: Round 1 recorded its own acceptance as a dated row', () => {
  // BUG-010. This is only possible because 01-docs/09-change-control/ moved to Round 1 —
  // a file every round writes to is created by the first round that writes to it.
  assert.deepEqual(acceptedStages(changeLog), ['Round 1 — the idea'])
})

test('GOLD-001: no state, progress or acceptance file exists anywhere', () => {
  assert.deepEqual(forbiddenStateFiles(Object.keys(workspace)), [])
})

// --- What is honestly still open --------------------------------------------------------------

test('GOLD-001: gaps are recorded as [TODO], not filled with plausible values', () => {
  // The distinction ADR-003 step 4 rests on. Express depth asked two questions, so most
  // fields are genuinely unknown — and an invented value is indistinguishable from a real
  // one once written down (BR-003).
  const count = Object.values(workspace).reduce((n, t) => n + todos(t).length, 0)
  assert.ok(count > 0, 'a two-question interview cannot honestly fill an intent document')
  assert.ok(count < 40, 'but a workspace that is nothing but TODOs is not a specification')
})

test('GOLD-001: the three failing scorers are the KNOWN Round-1 incompleteness, not new bugs', () => {
  const r = score({ workspace, library, rounds: 1, outside: [] })
  const failing = r.breaches.map((b) => b.name).sort()

  // These fail because rounds 2-8 do not exist yet (intake.md Step 3 stops after Round 1):
  // the [TODO]s pair with Q-### rows in open-questions.md, and intent.md links to
  // constraints-and-non-goals.md — both Round 2 files. Naming them here is the point: the
  // day this list changes, something real changed.
  assert.deepEqual(failing, ['ids_resolve', 'structural_checks', 'todo_pairing'])

  // And these are the ones that must hold at ANY round.
  const ok = (name) => r.results.find((x) => x.name === name).atFloor
  for (const name of ['no_leftover_template', 'no_example_content', 'boundary_respected', 'no_code_written']) {
    assert.equal(ok(name), true, `${name} must pass in a partial workspace too`)
  }
})

test('GOLD-001: todo_density is recorded, still ungated — one run of the ten Q-014 needs', () => {
  const r = score({ workspace, library, rounds: 1, outside: [] })
  const density = r.results.find((x) => x.name === 'todo_density')
  assert.equal(density.floor, null, 'Q-014 stays open until ten real runs exist')
  assert.ok(density.value > 0, 'and this run contributes a real number rather than a guess')
})
